package roi

import (
	"encoding/json"
	"image"
	"math"
	"os"
	"testing"
)

// vtkStencilFixture is testdata/upstream/vtk/stencil.json, generated by
// dicom-go-validation/scripts/vtk_fixtures.py with VTK 9.6.2:
// vtkLassoStencilSource polygons and vtkImageEllipsoidSource ellipses as
// masks of voxel centres.
type vtkStencilFixture struct {
	Width    int `json:"width"`
	Height   int `json:"height"`
	Polygons []struct {
		Name     string   `json:"name"`
		Vertices [][2]int `json:"vertices"`
		Mask     []string `json:"mask"`
	} `json:"polygons"`
	Ellipses []struct {
		Name    string   `json:"name"`
		Corners [][2]int `json:"corners"`
		Mask    []string `json:"mask"`
	} `json:"ellipses"`
}

func loadStencilFixture(t *testing.T) vtkStencilFixture {
	t.Helper()
	data, err := os.ReadFile("../testdata/upstream/vtk/stencil.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture vtkStencilFixture
	if err := json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	return fixture
}

// onPolygonEdge reports whether the pixel centre (x, y) lies on an edge.
func onPolygonEdge(x, y int, vertices []image.Point) bool {
	for i := range vertices {
		a, b := vertices[i], vertices[(i+1)%len(vertices)]
		cross := (b.X-a.X)*(y-a.Y) - (b.Y-a.Y)*(x-a.X)
		if cross == 0 && x >= min(a.X, b.X) && x <= max(a.X, b.X) && y >= min(a.Y, b.Y) && y <= max(a.Y, b.Y) {
			return true
		}
	}
	return false
}

func maskDifferences(t *testing.T, mask *RasterMask, want []string, width, height int, allowed func(x, y int) bool) (onEdge int) {
	t.Helper()
	if len(want) != height {
		t.Fatalf("fixture mask has %d rows", len(want))
	}
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			if mask.Get(x, y) == (want[y][x] == '1') {
				continue
			}
			if allowed == nil || !allowed(x, y) {
				t.Fatalf("pixel (%d, %d) is %v, VTK %c", x, y, mask.Get(x, y), want[y][x])
			}
			onEdge++
		}
	}
	return onEdge
}

// TestPolygonRasterMatchesVTKStencil compares polygon rasterization with
// vtkLassoStencilSource: the masks agree except on pixel centres that lie
// exactly on an edge, where both tie-breaking rules are valid.
func TestPolygonRasterMatchesVTKStencil(t *testing.T) {
	fixture := loadStencilFixture(t)
	if len(fixture.Polygons) == 0 {
		t.Fatal("no polygons")
	}
	for _, p := range fixture.Polygons {
		t.Run(p.Name, func(t *testing.T) {
			vertices := make([]image.Point, len(p.Vertices))
			for i, v := range p.Vertices {
				vertices[i] = image.Pt(v[0], v[1])
			}
			mask := VectorROI{Shape: ROIPolygon, Points: vertices}.Rasterize(fixture.Width, fixture.Height)
			edge := maskDifferences(t, mask, p.Mask, fixture.Width, fixture.Height, func(x, y int) bool { return onPolygonEdge(x, y, vertices) })
			t.Logf("%d edge pixels resolved differently", edge)
			// Analytic check: the pixel count stays within half the
			// perimeter of the shoelace area.
			var area2, perimeter float64
			for i := range vertices {
				a, b := vertices[i], vertices[(i+1)%len(vertices)]
				area2 += float64(a.X*b.Y - b.X*a.Y)
				perimeter += math.Hypot(float64(b.X-a.X), float64(b.Y-a.Y))
			}
			count := 0
			for y := 0; y < fixture.Height; y++ {
				for x := 0; x < fixture.Width; x++ {
					if mask.Get(x, y) {
						count++
					}
				}
			}
			if d := math.Abs(float64(count) - math.Abs(area2)/2); d > perimeter/2 {
				t.Fatalf("%d pixels for an area of %g", count, math.Abs(area2)/2)
			}
		})
	}
}

// TestEllipseRasterMatchesVTKEllipsoidSource compares the ellipse inscribed
// in two corners with vtkImageEllipsoidSource of the same centre and radii:
// the masks are identical.
func TestEllipseRasterMatchesVTKEllipsoidSource(t *testing.T) {
	fixture := loadStencilFixture(t)
	if len(fixture.Ellipses) == 0 {
		t.Fatal("no ellipses")
	}
	for _, e := range fixture.Ellipses {
		t.Run(e.Name, func(t *testing.T) {
			roi := VectorROI{Shape: ROIEllipse, Points: []image.Point{image.Pt(e.Corners[0][0], e.Corners[0][1]), image.Pt(e.Corners[1][0], e.Corners[1][1])}}
			maskDifferences(t, roi.Rasterize(fixture.Width, fixture.Height), e.Mask, fixture.Width, fixture.Height, nil)
		})
	}
}
